ALTER TABLE public.users ADD COLUMN IF NOT EXISTS username text;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS password_hash text;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS failed_login_attempts integer NOT NULL DEFAULT 0 CHECK (failed_login_attempts >= 0);
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS locked_until timestamptz;
CREATE UNIQUE INDEX IF NOT EXISTS users_username_ci_unique_idx ON public.users (lower(username)) WHERE username IS NOT NULL;
CREATE INDEX IF NOT EXISTS users_local_login_lookup_idx ON public.users (username) WHERE username IS NOT NULL AND active = true;
ALTER TABLE public.users ADD CONSTRAINT users_local_credentials_complete_chk CHECK ((username IS NULL AND password_hash IS NULL) OR (username IS NOT NULL AND password_hash IS NOT NULL));
REVOKE ALL ON TABLE public.users FROM anon, authenticated;
